    "fields": {
      "name": "Fantasma Faminto",
      "description": "Fantasmas famintos surgem daqueles que não receberam enterros adequados ou cujos túmulos foram negligenciados. Eles não estão vinculados a um local ou item, mas são compelidos a ver oportunidades para cometer boas ações na esperança de obter favores que possam ajudá-los a alcançar o descanso final. Contudo, a sua necessidade de se alimentarem de energia viva entra muitas vezes em conflito com este objectivo.\nPresos ao mundo após a morte por emoções poderosas que não foram resolvidas, os fantasmas assombram os vivos como tristes ecos do que eram antes. As regras para criar um fantasma começam na página 160 do Monster Core.",
      "size": "Médio",
      "senses": {
        "darkvision": "visão no escuro"
      },
      "languages": {
        "common": "comum",
        "necril": "necril"
      },
      "defenses": {
        "immunities": [
          "sangrar",
          "efeitos de morte",
          "doença",
          "paralisado",
          "tóxico",
          "precisão",
          "inconsciente"
        ],
        "resistances": [
          "dano total 5, exceto força, toque fantasma, espírito, vitalidade"
        ],
        "weaknesses": []
      },
      "attacks": {
        "yayQemggwK7HvtD6": {
          "name": "Toque Fantasmagórico",
          "damage": "2d8+4 vazio"
        }
      },
      "actions": {
        "lqnQneH97CzrjdJc": {
          "name": "Visão Viva",
          "description": "Embora tenham mais de 30 HP, o fantasma faminto parece ser uma criatura viva. Eles têm um resultado automático de 34 em testes de Enganação e CDs para ocultar seu status de morto-vivo e podem Alimentar-se dos Vivos secretamente."
        },
        "lNA7SL1bucW3ZHcL": {
          "name": "Alimente-se dos vivos",
          "description": "O fantasma faminto toca uma criatura viva ao seu alcance para roubar sua força vital. Se o fantasma estiver em seu rosto vivo, ele pode disfarçar Feed on the Living como um toque benigno e atrasar os efeitos por até 1 minuto, mantendo o alvo inconsciente do efeito. Uma criatura pode ser afetada por apenas um Alimentar dos Vivos retardado por vez, e se o fantasma perder sua aparência viva durante esse minuto, o efeito retardado será perdido. Quando Alimentar os Vivos entra em vigor, o alvo sofre (2d8+4)[void] de dano, dependendo do resultado de seu teste de resistência (fortitude, dc:24).\nSucesso Crítico A energia vital do alvo domina o fantasma. O fantasma faminto sofre 5[vitalidade] de dano e o alvo não é afetado.\nSucesso O alvo sofre metade do dano e o fantasma faminto recupera HP igual ao dano causado.\nFalha O alvo sofre dano total e fica Enfraquecido 1 por 1 minuto, e o fantasma faminto recupera HP igual ao dano causado.\nFalha Crítica O alvo sofre o dobro de dano e fica Enfraquecido 2 por 1 minuto, e o fantasma faminto recupera HP igual ao dano causado."
        },
        "UOnqLU2V5n002Crc": {
          "name": "Desfazer Voraz",
          "description": "Em cada período de 24 horas, o fantasma faminto deve usar Feed on the Living para consumir 30 HP (qualquer HP que o fantasma ganharia conta para esse total, mesmo que o fantasma tenha HP suficiente para não recuperar a quantidade total). Se o fantasma não tiver consumido HP suficiente, ele se alimentará de forma imprudente e imprudente de qualquer criatura viva que encontrar até ficar saciado."
        },
        "SUvl7lPOVDiTyjX4": {
          "name": "Rejuvenescimento",
          "description": "Quando um fantasma faminto é destruído, ele se recupera após [[/gmr 2d4 #days]]{2d4 dias} totalmente curado no local onde foi destruído pela última vez. Eles só são destruídos permanentemente quando recebem um enterro adequado, têm seu túmulo limpo e mantido por pelo menos um ano ou são julgados como redimidos por Pharasma."
        },
        "3R8Ms4mec7mI7Vcv": {
          "name": "Cura do Vazio",
          "description": ""
        }
      },
      "spellcasting": {}
    }
