      "name": "Vulpinal",
      "description": "Vulpinals servem como músicos e menestréis astutos e inteligentes dos agathions. Incrivelmente distantes, esses humanóides semelhantes a raposas adoram viajar para aprender e ensinar todas as canções, danças, mitos e tradições que puderem encontrar. Embora prefiram viajar sozinhos, os vulpinais são extremamente sociáveis ​​com aqueles que encontram em suas jornadas. Eles gostam de participar nas festividades das culturas que encontram e são conhecidos por formar pequenos grupos de viagem de indivíduos com ideias semelhantes se acreditarem que a sua experiência partilhada pode ser benéfica.",
