      "actions": {
        "Ql1Y3RVAWOqWARFL": {
          "name": "Telepatia 100 pés (30 metros)",
          "description": ""
        },
        "zkcQGrvQXeO0d4YV": {
          "name": "+2 para Sentir Motivo",
          "description": ""
        },
        "eyJ8okEtlxlLWhjy": {
          "name": "Rede de Informação",
          "description": "O dragão pode tentar um teste de Sociedade para Recordar Conhecimento no lugar de um teste para Coletar Informações, recordando informações de informantes anteriores."
        },
        "vSiPTgWIPTPTQIaI": {
          "name": "+2 Status para todos os salvamentos vs. Oculto",
          "description": ""
        },
        "VnvkdDxkW7wfBMjT": {
          "name": "Solução Diplomática",
          "description": "Acionar a iniciativa Dragon Rolls\nEfeito O dragão atinge todos os inimigos que pode ver dentro de @Template[emanation|distance:60]{60 pés (18 metros)} com Calm aumentado para um Rank igual à metade do nível do dragão arredondado para cima (verificar (vontade, dc:23) salvar). O dragão não precisa Sustentar este efeito, mas se o dragão realizar qualquer ação hostil contra os afetados, ele quebra o efeito para todas as criaturas."
        },
        "XZUptOpkSx0PYtkI": {
          "name": "Sussurro Distrativo",
          "description": "Gatilho O dragão é alvo de um ataque\nEfeito Uma voz misteriosa sussurra algo desconcertante no ouvido da criatura desencadeadora, infligindo uma penalidade de circunstância de -2 ao ataque desencadeador.\nEfeito: Sussurro Distrativo"
        },
        "WdFNthO0BdxIqruL": {
          "name": "Respiração de Cogitação",
          "description": "O dragão libera um miasma confuso, causando 6d6[mental|options:area-damage] de dano em um @Template[type:cone|distance:30] (check (will, dc:25, basic, options:area-effect,inflicts:stupefied) save). Uma criatura que falhe no teste fica Estupefata 1 (Estupefada 2 em caso de falha crítica) por 1 minuto. O dragão não pode usar Sopro de Cogitação novamente por [[/gmr 1d4 #Recharge Sopro de Cogitação]]{1d4 rodadas}."
        },
        "foIbgbTavh92IEGM": {
          "name": "Frenesi Dracônico",
          "description": "O dragão faz dois golpes de garra e um golpe de cauda em qualquer ordem."
        },
        "gnFWINeBp8o39lnC": {
          "name": "Momento Dracônico",
          "description": "O dragão recarrega seu Sopro de Cogitação sempre que consegue um acerto crítico com um Golpe."
        },
        "EZmRWrf1EQnbLdow": {
          "name": "Roubar Conhecimento",
          "description": "O dragão arranca um fragmento de conhecimento da mente de uma criatura dentro de 60 pés (18 metros), escolhendo uma habilidade para afetar. A criatura deve tentar um teste de resistência (vontade, dc:23).\nSucesso A criatura não é afetada.\nFalha No minuto seguinte, a criatura sofre uma penalidade de -1 em testes usando aquela habilidade, e o dragão recebe um bônus de status de +1 por usar aquela habilidade.\nFalha Crítica Como falha, mas a penalidade é –2 e o bônus é +2."
        }
      },
